using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Windows.Forms;
namespace WinterDesk {
internal sealed class SnowBall:IDisposable {
 internal Layer Window=new Layer();internal Sprite Image;internal float Scale=1;internal double X,Y,VX,VY,Area,Angle;internal bool Held,Thrown;internal double GrabX,GrabY;internal readonly ThrowGesture Gesture=new ThrowGesture();internal SnowBall Parent;internal double Radius {get{return Math.Sqrt(Math.Max(16,Area)/Math.PI);}}
 internal bool Face;internal int Size;
 internal readonly int PaintVariant=(int)((uint)Artwork.NewSeed()%8);
 internal void Paint(){int r=(int)Math.Ceiling(Radius),size=r*2+8;using(var b=Artwork.Canvas(size,size)){using(var g=Graphics.FromImage(b))SnowBallArt.Draw(g,size*.5f,size*.5f+r,r,Angle,PaintVariant);if(Image==null||Image.Width!=b.Width||Image.Height!=b.Height){if(Image!=null)Image.Dispose();Image=new Sprite(b);}else Image.Upload(b);Size=size;Window.Paint(Image,(int)(X-size*.5),(int)(Y-size*.5));}Window.Show(true);}

 public void Dispose(){Window.Dispose();if(Image!=null)Image.Dispose();}
}
internal sealed partial class Controller {
 readonly List<SnowBall> snowBalls=new List<SnowBall>();SnowBall activeBall;double toyPaint;
 internal static int PetFrame(PetMotion p){if(p.State==PetState.Sliding)return 320+Math.Min(31,(int)(p.Age/.38*32));if(p.State==PetState.Running)return 192+(int)(PenguinGait.Phase(p.RunDistance,p.Scale)*128)%128;int action=0;double phase=p.Time*2;switch(p.State){case PetState.Held:action=0;break;case PetState.Falling:action=0;phase=p.Time*2;break;case PetState.Landing:action=2;phase=Math.Min(.999,p.Age/.42);break;case PetState.GettingUp:action=3;phase=Math.Min(.999,p.Age/.62);break;case PetState.Dusting:action=4;phase=Math.Min(.999,p.Age/.48);break;default:action=5;break;}return action*32+(int)((phase-Math.Floor(phase))*32);}
 void StartBall(Surface s,int x,int y){if(snowBalls.Count>=24)return;double px=s.Bounds.Left+x,py=s.BaseY-s.Model.Height+y,radius=6*s.Scale;double area=SnowContact.Collect(s.Model,s.Bounds.Left,s.BaseY,px,py-radius*.6,px,py-radius*.6,radius);if(area<1)return;var b=new SnowBall{Scale=s.Scale,Area=area,X=px,Y=py-Math.Sqrt(area/Math.PI),Held=true};b.GrabX=0;b.GrabY=py-b.Y;snowBalls.Add(b);activeBall=b;b.Gesture.Begin(b.X,b.Y,watch.Elapsed.TotalSeconds);ConfigureBall(b);b.Paint();}
 void GrowBall(SnowBall b,double oldX,double oldY){if(Math.Abs(b.X-oldX)+Math.Abs(b.Y-oldY)<.25)return;double radius=b.Radius;foreach(var surface in AllSurfaces()){bool blocked=false;foreach(var cut in surface.Blockers)if(cut.Contains((int)b.X,(int)b.Y)){blocked=true;break;}if(blocked)continue;b.Area+=SnowContact.Collect(surface.Model,surface.Bounds.Left,surface.BaseY,oldX,oldY,b.X,b.Y,radius);}b.Angle+=(b.X-oldX)/Math.Max(1,radius);}
 void RollBall(Surface s,int x,int y){if(activeBall==null)return;var b=activeBall;double oldX=b.X,oldY=b.Y;b.X=s.Bounds.Left+x-b.GrabX;b.Y=s.BaseY-s.Model.Height+y-b.GrabY;GrowBall(b,oldX,oldY);b.Gesture.Move(b.X,b.Y,watch.Elapsed.TotalSeconds,b.Scale);b.Paint();}
 void ConfigureBall(SnowBall b){b.Window.SetInput(true);b.Window.Hit=delegate(int x,int y){double dx=x-b.Size/2,dy=y-b.Size/2;return dx*dx+dy*dy<=b.Radius*b.Radius;};b.Window.MouseDown=delegate(int x,int y){if(activeBall!=null)return;b.Parent=null;b.Held=true;b.Thrown=false;b.GrabX=b.Window.X+x-b.X;b.GrabY=b.Window.Y+y-b.Y;activeBall=b;b.Gesture.Begin(b.X,b.Y,watch.Elapsed.TotalSeconds);};b.Window.MouseDrag=delegate(int x,int y){if(activeBall!=b)return;double oldX=b.X,oldY=b.Y;b.X=b.Window.X+x-b.GrabX;b.Y=b.Window.Y+y-b.GrabY;GrowBall(b,oldX,oldY);b.Gesture.Move(b.X,b.Y,watch.Elapsed.TotalSeconds,b.Scale);b.Paint();};b.Window.MouseUp=delegate(int x,int y){if(activeBall==b)ReleaseBall();};}
 void ReleaseBall(){var b=activeBall;if(b==null)return;activeBall=null;b.Held=false;b.Gesture.Release(watch.Elapsed.TotalSeconds,out b.VX,out b.VY);b.Thrown=Math.Sqrt(b.VX*b.VX+b.VY*b.VY)>160*b.Scale;if(b.Thrown){b.Paint();return;}b.VX=b.VY=0;foreach(var other in snowBalls){if(other==b||other.Held||other.Radius<b.Radius*.85||snowBalls.Exists(child=>child!=b&&child.Parent==other))continue;bool cycle=false;for(var p=other;p!=null;p=p.Parent)if(p==b)cycle=true;if(cycle)continue;double top=other.Y-other.Radius-b.Radius;if(Math.Abs(b.X-other.X)<other.Radius*.9&&Math.Abs(b.Y-top)<Math.Max(45,other.Radius)){b.Parent=other;b.X=other.X;b.Y=top;int depth=0;for(var p=b;p!=null;p=p.Parent)depth++;if(depth==3)b.Face=true;break;}}b.Paint();if(b.Face)AwakenStack(b);}
 void AnimateSnowToys(double dt,double now){bool paint=now>=toyPaint;if(paint)toyPaint=now+1.0/60;AnimateSnowImpacts(dt);foreach(var b in snowBalls.ToArray()){if(!snowBalls.Contains(b))continue;if(b.Held){Native.POINT p;Native.GetCursorPos(out p);if(activeBall==b&&(Native.GetAsyncKeyState(1)&0x8000)==0)ReleaseBall();continue;}if(b.Parent!=null){b.X=b.Parent.X;b.Y=b.Parent.Y-b.Parent.Radius-b.Radius;}else{double remain=Math.Min(.1,dt);bool destroyed=false;while(remain>0){double step=Math.Min(remain,1.0/120),oldY=b.Y,oldX=b.X;b.VY+=900*b.Scale*step;double nextX=b.X+b.VX*step,nextY=b.Y+b.VY*step;if(b.Thrown){var hit=SnowThrowPhysics.Sweep(b.X,b.Y,nextX,nextY,b.Radius,ledges);if(hit.Hit){HitWindow(b,hit);destroyed=true;break;}}b.X=nextX;b.Y=nextY;b.Angle+=(b.X-oldX)/Math.Max(1,b.Radius);double floor=FloorAt(b.X,b.Y)-b.Radius;foreach(var l in ledges)if(l.Supports(b.X)&&oldY+b.Radius<=l.Bounds.Top+1&&b.Y+b.Radius>=l.Bounds.Top&&b.VY>=0)floor=Math.Min(floor,l.Bounds.Top-b.Radius);if(b.Y>=floor){b.Y=floor;b.VY=0;b.VX*=Math.Exp(-step*3.8);if(Math.Abs(b.VX)<8)b.VX=0;}remain-=step;}if(destroyed)continue;}var area=SystemInformation.VirtualScreen;if(b.X<area.Left-600||b.X>area.Right+600||b.Y>area.Bottom+600){snowBalls.Remove(b);b.Dispose();continue;}if(paint){if(b.Image==null||b.Thrown)b.Paint();else b.Window.Move((int)(b.X-b.Size/2),(int)(b.Y-b.Size/2));}}}
 void ClearSnowToys(){ClearSnowImpacts();foreach(var b in snowBalls)b.Dispose();snowBalls.Clear();activeBall=null;}
 internal int SnowBallCount {get{return snowBalls.Count;}}

}
}
